function plgFrames(){return [].slice.call(document.querySelectorAll('iframe.plg-donate-iframe,iframe[src*="pledge.to/widgets/donate"]'))}
function setAmt(f){try{var u=new URL(f.src),cur=u.searchParams.get('amount')||'';var want=giveAmt>0?String(giveAmt):'';if(cur===want)return;if(want)u.searchParams.set('amount',want);else u.searchParams.delete('amount');f.src=u.toString()}catch(e){}}
