var GPK=[
 {id:'shirt',min:500,auto:1,n:'Access to buy Legalize Rick Inception shirts',fmv:0,inv:'',what:'A discount code to buy the supporters-only shirt at cost in our store. The shirt and shipping are paid separately and are not part of your donation.',terms:[]},
 {id:'zoomf',min:5000,auto:1,n:'Zoom with the filmmakers',fmv:0,inv:'',what:'A group Zoom with Nirvan and the team, plus the Film Advisory WhatsApp group.',terms:['Group sessions, scheduled by the team.']},
 {id:'arc',min:25000,n:'A week at Arcturus',fmv:3500,inv:'A week at Arcturus',what:'A one-week stay at Arcturus, the house Rick built in Sarasota, Florida in 1975, where MAPS began.',terms:['The house is being restored and will not be available until late 2027.','Dates are subject to availability and set later by mutual agreement.','Before your stay you will receive the house rules and a guest agreement to read and sign.','Travel is not included. Up to 4 guests including you.'],agree:1},
 {id:'zoomr',min:25000,auto:1,n:'Zoom with Rick Doblin',fmv:0,inv:'Zoom with Rick Doblin',what:'An Inner Circle Zoom with Rick Doblin, plus the Inner Circle WhatsApp group.',terms:['Group sessions, scheduled around Rick’s calendar.']},
 {id:'prem',min:25000,n:'Premiere invite',fmv:150,inv:'Premiere invite',what:'An invitation for you and a guest to the film’s premiere.',terms:['Date and city to be announced. Travel is not included.']},
 {id:'din',min:100000,n:'Private dinner with Rick',fmv:400,inv:'Private dinner with Rick',what:'A private dinner with Rick Doblin.',terms:['Date and place set later by mutual agreement, subject to Rick’s availability.','Travel is not included.'],agree:1},
 {id:'ther',min:250000,n:'Guided therapy with Rick in Arcturus',fmv:2500,inv:'Guided therapy with Rick',what:'A guided session with Rick Doblin at Arcturus.',terms:['Not medical treatment. It takes place only in a form that is legal at the time and place, after a screening call.','Available from late 2027, subject to availability and mutual agreement.','You will receive a participant agreement to read and sign first. We may change or withdraw this perk on legal advice.'],agree:1}];
var GCO={on:0,step:1,amt:0,ans:{},ack:{},agree:{}};
function gcoLeft(p){if(!p.inv||!INV[p.inv]||!INV[p.inv].lim)return null;return invLeft(INV[p.inv])}
function gcoElig(){return GPK.filter(function(p){return !p.auto&&GCO.amt>=p.min&&!(INV[p.inv]&&INV[p.inv].on===0)})}
function gcoAuto(){return GPK.filter(function(p){return p.auto&&GCO.amt>=p.min})}
function gcoAutoHtml(){var A=gcoAuto();return A.length?'<div class="gcoinc"><b>Also included with your gift</b><ul>'+A.map(function(p){return '<li><b>'+esc(p.n)+'.</b> '+esc(p.what)+'</li>'}).join('')+'</ul></div>':''}
function gcoOpen(a){GCO={on:1,step:a>0?2:1,amt:a>0?a:0,ans:{},ack:{},agree:{}};if(GCO.step===2&&!gcoElig().length)GCO.step=3;gcoDraw();document.documentElement.classList.add('wath-noscroll')}
function gcoClose(){var o=T.querySelector('.gco');if(o)o.parentNode.removeChild(o);GCO.on=0;document.documentElement.classList.remove('wath-noscroll')}
function gcoFmv(){return gcoElig().reduce(function(t,p){return t+(GCO.ans[p.id]==='y'?p.fmv:0)},0)}
function gcoOk(){return gcoElig().every(function(p){var a=GCO.ans[p.id];if(!a)return false;if(a==='n'||a==='w')return true;var l=gcoLeft(p);if(l===0)return true;return (!p.fmv||GCO.ack[p.id])&&(!p.agree||GCO.agree[p.id])})}
function gcoDraw(){var o=T.querySelector('.gco');if(!o){o=document.createElement('div');o.className='gco';o.setAttribute('role','dialog');o.setAttribute('aria-modal','true');o.setAttribute('aria-label','Test checkout');T.appendChild(o)}
  var a=GCO.amt,lv=levelFor(a),E=gcoElig(),f=gcoFmv(),h='';
  var ban='<div class="gcob"><b>TEST CHECKOUT</b> This is not a real gift. You will not be charged. For testing the perk flow only.</div>';
  var steps='<div class="gcos">'+['Amount','Perks','Review'].map(function(s,i){return '<span'+(GCO.step===i+1?' class="on"':GCO.step>i+1?' class="dn"':'')+'>'+(i+1)+'. '+s+'</span>'}).join('')+'</div>';
  if(GCO.step===1){h='<h3>How much would you like to give?</h3><div class="gcoa">'+[50,500,5000,25000,100000,250000].map(function(v){return '<button class="'+(a===v?'on':'')+'" data-gco="amt" data-v="'+v+'">'+money(v)+'</button>'}).join('')+'</div><label class="gcol">Or enter an amount<span class="gcoi">$<input data-gcoamt inputmode="numeric" value="'+(a||'')+'" placeholder="0"></span></label><p class="gcon">'+(lv?'This gift reaches <b>'+esc(lv.n)+'</b> ('+lv.l+').'+(E.length?' It qualifies for '+E.length+' perk'+(E.length===1?'':'s')+' you can choose on the next step, subject to availability.':''):'Gifts of $5 or more put your name on the donor wall.')+'</p><div class="gcof"><button class="btn" data-gco="x">Cancel</button><button class="btn pri" data-gco="next"'+(a>0?'':' disabled')+'>Continue</button></div>'}
  else if(GCO.step===2){h='<h3>Your gift qualifies for these perks</h3><p class="gcon">For each one, tell us whether you want it. Perks with a market value reduce the tax-deductible part of your gift. Saying no keeps your whole gift deductible.</p>'+E.map(function(p){var an=GCO.ans[p.id],l=gcoLeft(p),out=l===0;return '<div class="gcop'+(an==='y'?' y':'')+'"><div class="gcoph"><b>'+esc(p.n)+'</b><span>'+(p.fmv?'Estimated fair market value '+money(p.fmv):'No market value')+(l!=null?' · '+(out?'Fully claimed':l+' of '+INV[p.inv].total+(INV[p.inv].unit?' '+INV[p.inv].unit:'')+' available'):'')+'</span></div><p>'+esc(p.what)+'</p>'+(p.terms.length?'<ul>'+p.terms.map(function(t){return '<li>'+esc(t)+'</li>'}).join('')+'</ul>':'')
     +(out?'<p class="gcoout">This perk is fully claimed right now.</p><div class="gcoq"><button class="'+(an==='w'?'on':'')+'" data-gco="ans" data-p="'+p.id+'" data-v="w">Notify me if one opens up</button><button class="'+(an==='n'?'on':'')+'" data-gco="ans" data-p="'+p.id+'" data-v="n">Continue without it</button></div>':'<div class="gcoq"><span>Do you want this perk?</span><button class="'+(an==='y'?'on':'')+'" data-gco="ans" data-p="'+p.id+'" data-v="y">Yes, I want it</button><button class="'+(an==='n'?'on':'')+'" data-gco="ans" data-p="'+p.id+'" data-v="n">No thanks</button></div>'
     +(an==='y'?(p.fmv?'<label class="gcock"><input type="checkbox" data-gcock="ack" data-p="'+p.id+'"'+(GCO.ack[p.id]?' checked':'')+'> I understand this perk&rsquo;s estimated fair market value of '+money(p.fmv)+' is not tax-deductible, so my deductible amount goes down by '+money(p.fmv)+'.</label>':'')+(p.agree?'<label class="gcock"><input type="checkbox" data-gcock="agree" data-p="'+p.id+'"'+(GCO.agree[p.id]?' checked':'')+'> I have read the conditions above. Dates are set later by mutual agreement, and I will sign the house rules and agreement before taking part.</label>':''):''))+'</div>'}).join('')
     +gcoAutoHtml()+'<div class="gcof"><button class="btn" data-gco="back">Back</button><button class="btn pri" data-gco="next"'+(gcoOk()?'':' disabled')+'>Review my gift</button></div>'}
  else if(GCO.step===3){var ch=E.filter(function(p){return GCO.ans[p.id]==='y'&&gcoLeft(p)!==0});h='<h3>Review your gift</h3><div class="gcor"><div><span>Gift</span><b>'+money(a)+'</b></div><div><span>Level</span><b>'+(lv?esc(lv.n):'–')+'</b></div><div><span>Perks you chose</span><b>'+(ch.length?ch.map(function(p){return esc(p.n)}).join('<br>'):'None')+'</b></div><div><span>Value of perks (not deductible)</span><b>'+(f?'− '+money(f):'$0')+'</b></div><div class="tot"><span>Estimated tax-deductible amount</span><b>'+money(Math.max(0,a-f))+'</b></div></div>'+gcoAutoHtml()+'<p class="gcon">Credits, the donor wall and updates are included automatically. Your receipt would show the gift and the value of any perks you chose. Fair market values here are placeholders.</p><div class="gcof"><button class="btn" data-gco="back">Back</button><button class="btn pri" data-gco="pay">Continue to payment (test, no charge)</button></div>'}
  else{var ch2=E.filter(function(p){return GCO.ans[p.id]==='y'&&gcoLeft(p)!==0});h='<h3>Test complete</h3><p class="gcon">No payment was taken. In the real version, Pledge&rsquo;s secure checkout would open now for <b>'+money(a)+'</b>, and we would save your perk choices with your gift: '+(ch2.length?ch2.map(function(p){return esc(p.n)}).join(', '):'no perks')+'. Your receipt would show a deductible amount of <b>'+money(Math.max(0,a-gcoFmv()))+'</b>.</p><p class="gcon">After the gift, each perk shows up in <b>My perks</b> to schedule or ship.</p><div class="gcof"><button class="btn" data-gco="x">Close</button><button class="btn pri" data-gco="perks">See My perks at this level</button></div>'}
  o.innerHTML='<div class="gcoc">'+ban+'<button class="gcox" data-gco="x" aria-label="Close">&times;</button>'+(GCO.step<4?steps:'')+h+'</div>'}
T.addEventListener('click',function(e){var b=e.target.closest&&e.target.closest('[data-gco]');if(!b||!b.closest('.gco')){if(e.target.classList&&e.target.classList.contains('gco'))gcoClose();return}var k=b.getAttribute('data-gco'),v=b.getAttribute('data-v'),p=b.getAttribute('data-p');
  if(k==='x'){gcoClose();return}if(k==='amt'){GCO.amt=+v;GCO.ans={};gcoDraw();return}if(k==='back'){GCO.step=GCO.step===3&&!gcoElig().length?1:GCO.step-1;gcoDraw();return}
  if(k==='next'){GCO.step=GCO.step===1&&!gcoElig().length?3:GCO.step+1;gcoDraw();T.querySelector('.gco').scrollTop=0;return}if(k==='ans'){GCO.ans[p]=v;gcoDraw();return}if(k==='pay'){GCO.step=4;gcoDraw();return}
  if(k==='perks'){var amt=GCO.amt;gcoClose();PF.pv=[1250,5000,25000,100000,250000].filter(function(x){return x<=amt}).pop()||0;MEM.tab='perks';ADM.on=false;try{openMember(true)}catch(x){}}});
T.addEventListener('change',function(e){var c=e.target.closest&&e.target.closest('[data-gcock]');if(c){GCO[c.getAttribute('data-gcock')][c.getAttribute('data-p')]=c.checked;gcoDraw()}});
T.addEventListener('input',function(e){if(e.target.hasAttribute&&e.target.hasAttribute('data-gcoamt')){GCO.amt=Math.max(0,Math.round(+String(e.target.value).replace(/[^0-9.]/g,'')||0));GCO.ans={};var pos=e.target.selectionStart;gcoDraw();var i=T.querySelector('.gco [data-gcoamt]');if(i){i.focus();try{i.setSelectionRange(pos,pos)}catch(x){}}}});
function give(amt){if(GCO_TEST){gcoOpen(+amt>0?Math.round(+amt):0);return}giveAmt=+amt>0?Math.round(+amt):0;var a=document.getElementById('wath-plg');if(!a){location.href='/donate';return}
  if(!giveObs&&window.MutationObserver){giveObs=new MutationObserver(function(){plgFrames().forEach(setAmt)});giveObs.observe(document.body,{childList:true,subtree:true})}
  plgFrames().forEach(setAmt);a.click();
  var n=0,t=setInterval(function(){plgFrames().forEach(setAmt);if(++n>12)clearInterval(t)},250)}
