/* Filmmaker bios (text from the About page) */
var BIOS={"nirvan": ["Nirvan Mullick", "Director, Producer", "https://images.squarespace-cdn.com/content/v1/5cb1600577b90384f9245e9e/1555433778223-YF44T2R77O4M3UTN9J4O/nirvan_bw.jpg?format=300w", "50% 30%", "Nirvan Mullick is an award-winning filmmaker who tells stories that move people to act. His short “Caine’s Arcade” reached millions, sparked a worldwide movement of kids’ creativity and led him to found the nonprofit Imagination.org; years earlier, THE 1 SECOND FILM, a film anyone could help produce, helped shape modern crowdfunding. He studied at New College, the same school where Rick Doblin first tried psychedelics in 1971, and Rick appeared in Nirvan’s very first film there in 1996. Nirvan lives in Ojai, California, under a 250-year-old pecan tree."], "dream": ["Dream Mullick", "Producer", "https://images.squarespace-cdn.com/content/v1/5cb1600577b90384f9245e9e/1555431858411-Z2NV78ZE78PGR5BTJ8GZ/Dream_Mullick.jpg?format=300w", "50% 25%", "Dream Mullick is a producer and teacher who curates programs at the intersections of ancient ceremony and modern psychedelic science. As Interconnected's Director of Development, she helped her brother Nirvan create the UN Foundation's #EarthToParis Campaign that built momentum toward the Paris Climate Agreement. Dream has hosted the Psychedelic Healing Summit for the Shift Network, brought psychedelic curriculum to the Esalen Institute, and created Esalen's first digital hybrid program, Entheowheel. She has been producing with her brother since 2013, after working in commercial production in Albuquerque. Dream holds a BA in Business from the Anderson School of Management at University of New Mexico."], "darren": ["Darren Aronofsky", "Executive Producer", "https://images.squarespace-cdn.com/content/v1/5cb1600577b90384f9245e9e/9b0e790b-0826-45ce-b5e3-2b2b28f01dbf/darren_aronofsky.jpeg?format=300w", "50% 30%", "Darren Aronofsky is an Academy Award–nominated American film director, screenwriter and film producer. He attended Harvard University and AFT to study both live-action and animation. Darren’s films include Pi, Requiem for a Dream, Black Swan, The Fountain, The Wrestler, Noah, Mother! and The Whale. Darren directed Postcard from Earth, the first film to screen at “The Sphere” in Las Vegas, and is working on the Elon Musk biopic with A24. Aronofsky is the founder and head of the production company, Protozoa Pictures."], "jeffrey": ["Jeffrey Schneider", "Cinematographer", "https://images.squarespace-cdn.com/content/v1/5cb1600577b90384f9245e9e/1555431789123-2KB2SGD4YE7YE4AD0JE5/IMG_20181217_162143.jpg?format=300w", "50% 30%", "Jeffrey Schneider is a Los Angeles-based Director of Photography with over 15 years of experience filming documentaries, television shows, commercials, and feature films. His work has appeared on Showtime, ESPN, MTV, the History Channel, as well as at festivals including Sundance, Tribeca, South by Southwest, Berlin, and Seattle International Film Festival. Commercially he has worked with brands including Google, Dior, Nike, Microsoft, and Canon. Jeffrey has a BA in Film and Digital Media from the University of California, Santa Cruz, and studied Documentary Filmmaking at the San Francisco Art Institute."], "vickie": ["Vickie Curtis", "Story Consultant", "https://images.squarespace-cdn.com/content/v1/5cb1600577b90384f9245e9e/93eff408-ea57-4c5f-b815-a4908353c04b/Vickie_BW.png?format=300w", "50% 25%", "Vickie Curtis is an Emmy-winning filmmaker, writer, and story architect who has worked as a story consultant for documentaries including The Social Dilemma (Sundance, Netflix), Chasing Coral (Sundance, Netflix), and the upcoming Immortality Key documentary. The focus of her work involves elevating nonfiction film with the same strong characters and narrative arc that make great fiction so compelling. A theatre nerd at heart, she seeks stories that reveal the transformational and nourishing power of artistic expression."]};
