function liveCanSet(x){var me=LV.role;if(!x||!LV.member||x.id===LV.member.id||x.role==='owner')return [];if(me==='owner')return ['admin','manager','editor'];if(me==='admin'&&x.role!=='admin')return ['manager','editor'];return []}
