function liveUninvite(em){if(!SB||LV.roleBusy)return;LV.roleBusy=true;SB.rpc('cancel_staff_invite',{invite_email:em}).then(function(r){LV.roleBusy=false;toast(r&&r.error?'That was not allowed.':'Invitation cancelled.');LV.rows=null;renderMember()},function(){LV.roleBusy=false})}
